import sys

s = sys.stdin.readline().strip()
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
ok = True
for c in s:
    if c in '([{':
        stack.append(c)
    else:
        if not stack or stack.pop() != pairs[c]:
            ok = False
            break
print("YES" if ok and not stack else "NO")
